using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace PZ3D {static class FullLauncherIntegrationTests {
 static JavaScriptSerializer j=new JavaScriptSerializer();static Dictionary<string,object> D(object o){return j.Deserialize<Dictionary<string,object>>(j.Serialize(o));}static void Check(bool v,string n){if(!v)throw new Exception("FAIL: "+n);Console.WriteLine("PASS: "+n);}
 public static int Main(){try{Run();return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
 public static void Run(){string root=Path.Combine(LauncherTestPaths.Root,"integration-"+Guid.NewGuid().ToString("N")),game=Path.Combine(root,"game"),user=Path.Combine(root,"user"),data=Path.Combine(root,"data");Directory.CreateDirectory(game);Directory.CreateDirectory(user);File.WriteAllText(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[\"-Xmx4g\"]}");using(var c=new ModernController(game,user,data,true)){foreach(string action in new[]{"modProfiles","serverFavorites","taskGet","playtimeGet"}){var request=ModernHostPolicy.Validate("https://orange.local/index.html",j.Serialize(new{id="test",action=action,payload=new{}}));Check(D(c.Execute(action,new Dictionary<string,object>())).Count>0,"new native read allowed: "+action);}Check(!Directory.Exists(data),"fresh read endpoints don't write data");c.Execute("playtimeSettings",new Dictionary<string,object>{{"reminderMinutes",30}});Check(Convert.ToInt32(D(c.Execute("playtimeGet",null))["reminderMinutes"])==30,"playtime settings survive controller dispatch");string history=j.Serialize(c.Execute("taskGet",null));Check(history.Contains("completed")&&history.Contains("playtimeSettings"),"mutation result appears in durable task center");bool failed=false;try{c.Execute("memorySave",new Dictionary<string,object>{{"value",1},{"stamp","stale"}});}catch{failed=true;}Check(failed&&j.Serialize(c.Execute("taskGet",null)).Contains("failed"),"failed write appears as failed task not generic completion");c.Execute("maintenance",new Dictionary<string,object>{{"confirmed",true},{"kind","cache"}});Check(j.Serialize(c.Execute("taskGet",null)).Contains("清除多人缓存"),"task titles explain operation not internal action only");}using(var second=new ModernController(game,user,data,true))Check(j.Serialize(second.Execute("taskGet",null)).Contains("playtimeSettings"),"task history survives reopened controller");}
}}
